using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using NUnit.Framework;
using UnityEngine;
using UnityEditor.SceneManagement;
using SporeGobbo.Geometry.Preview.Editor;
namespace SporeGobbo.Geometry.Preview.Tests
{
 public sealed class Stage52Tests
 {
  static DiscoveryFixture fixture;static DiscoveryIndex index;
  [OneTimeSetUp]public void BuildInitialIndex(){fixture=new DiscoveryFixture(1024);index=new DiscoveryIndex(new StreamingWorld(1024,1024,47045,fixture),fixture);}
  sealed class Rig:IDisposable{public readonly StreamingWorld W;public readonly CaveDiscovery D;public readonly DiscoveredTerrainPresentation P;public Rig(){W=new StreamingWorld(1024,1024,47045,fixture);D=new CaveDiscovery(W,index);P=new DiscoveredTerrainPresentation(D);}public void Dispose()=>D.Dispose();}
  static void Settle(CaveDiscovery d){int n=0;while(d.PendingReleases>0&&n++<100)d.Tick(10);Assert.That(d.PendingReleases,Is.Zero);}
  static void Prepare(CaveDiscovery d,Point2 observer){double duration=d.Duration;d.Duration=0;d.Explore(observer);Settle(d);d.Duration=duration;}
  static Vector2 V(Point2 p)=>new Vector2((float)p.X,(float)p.Y);
  static bool Known(CaveDiscovery d,Point2 p)=>d.Known((int)p.X,(int)p.Y);
  static bool HasPath(StreamingWorld w,Point2 from,Point2 to,int size)=>new LabNavigation(w,from).TraceToRoot(to,size,new List<Point2>());
  [Test]public void InitialCavesExistPhysicallyWithoutDiscoveryOrPresentationLeak(){using(var r=new Rig()){foreach(int n in new[]{0,1,2,3,4,6}){var p=fixture.Centers[n];Assert.That(r.W.IsSolid((int)p.X,(int)p.Y),Is.False);Assert.That(Known(r.D,p),Is.False);Assert.That(r.P.IsSolid((int)p.X,(int)p.Y));}Assert.That(r.W.EditCount,Is.Zero);}}
  [Test]public void IndexCoversInitialFloorAcrossWhole1024WorldOnce(){Assert.That(index.InitialQueries,Is.EqualTo(1024L*1024));Assert.That(index.CellCount,Is.GreaterThan(50000));foreach(var p in new[]{fixture.Entry,new Point2(32.5,512.5),fixture.Centers[1]})Assert.That(index.ByCell.ContainsKey((int)p.Y*1024+(int)p.X));Assert.That(index.Regions.All(r=>r.Cells.Length<=1024));}
  [Test]public void StableIdsComeFromFixtureAndInitialChunkConnectivity(){var other=new DiscoveryIndex(new StreamingWorld(1024,1024,47045,fixture),fixture);Assert.That(other.Regions.Select(r=>r.Id),Is.EqualTo(index.Regions.Select(r=>r.Id)));Assert.That(other.ByCell.Count,Is.EqualTo(index.ByCell.Count));Assert.That(index.Regions.Count(r=>r.Id.StartsWith("fixture/network/")),Is.GreaterThan(8));}
  [Test]public void SealedPocketCannotBeDiscoveredByCameraOrNearbyExploration(){using(var r=new Rig()){Prepare(r.D,fixture.Approaches[0]);Assert.That(Known(r.D,fixture.Centers[0]),Is.False);for(int n=0;n<4;n++){var p=new FocusProjection(fixture.Centers[0],48,28,24,.25,.2,1.9,new Point2(0,n));p.Project(fixture.Centers[0]);r.D.Tick(1);}Assert.That(Known(r.D,fixture.Centers[0]),Is.False);}}
  [Test]public void ActualBreakthroughIsConnectedToKnownAccessibleFloor(){using(var r=new Rig()){var p=fixture.Approaches[0];Prepare(r.D,p);int before=r.D.DiscoveryEvents;Assert.That(r.W.Excavate(fixture.X-60,fixture.Y-4));Assert.That(r.D.ProcessChanges(p),Is.GreaterThan(0));r.D.Tick(0);Assert.That(Known(r.D,fixture.Centers[0]));Assert.That(r.D.DiscoveryEvents,Is.GreaterThan(before));Assert.That(r.W.EditCount,Is.EqualTo(1));}}
  [Test]public void RemoteExcavationDoesNotPretendToBePlayerBreakthrough(){using(var r=new Rig()){Prepare(r.D,fixture.Entry);int count=r.D.Remembered.Count;r.W.Excavate(fixture.X-20,fixture.Y-4);r.D.ProcessChanges(fixture.Entry);Assert.That(r.D.Remembered.Count,Is.EqualTo(count));Assert.That(Known(r.D,fixture.Centers[1]),Is.False);}}
  [TestCase(1,true)][TestCase(3,false)]public void OneCellDiscoveryDoesNotCertifyBuddyAccess(int size,bool expected){using(var r=new Rig()){Prepare(r.D,fixture.Approaches[0]);r.W.Excavate(fixture.X-60,fixture.Y-4);r.D.ProcessChanges(fixture.Approaches[0]);Assert.That(Known(r.D,fixture.Centers[0]));Assert.That(HasPath(r.W,fixture.Approaches[0],fixture.Centers[0],size),Is.EqualTo(expected));}}
  [Test]public void WideningPhysicalSealMakesThreeCellBuddyRouteValid(){using(var r=new Rig()){for(int x=-61;x<=-59;x++)r.W.Excavate(fixture.X+x,fixture.Y-4);Assert.That(HasPath(r.W,fixture.Approaches[0],fixture.Centers[0],3));}}
  [Test]public void ImmediatePocketAndGradualChamberHaveDifferentVisualGates(){using(var r=new Rig()){Prepare(r.D,fixture.Approaches[0]);r.W.Excavate(fixture.X-60,fixture.Y-4);r.D.ProcessChanges(fixture.Approaches[0]);Settle(r.D);Assert.That(r.P.IsSolid((int)fixture.Centers[0].X,(int)fixture.Centers[0].Y),Is.False);Prepare(r.D,fixture.Approaches[1]);r.W.Excavate(fixture.X-20,fixture.Y-4);r.D.ProcessChanges(fixture.Approaches[1]);Assert.That(Known(r.D,fixture.Centers[1]));Assert.That(r.P.IsSolid((int)fixture.Centers[1].X,(int)fixture.Centers[1].Y));Assert.That(HasPath(r.W,fixture.Approaches[1],fixture.Centers[1],1));r.D.Tick(.1);Assert.That(r.D.Visual.Count,Is.LessThan(r.D.Remembered.Count));Settle(r.D);Assert.That(r.P.IsSolid((int)fixture.Centers[1].X,(int)fixture.Centers[1].Y),Is.False);}}
  [Test]public void ConnectedNetworkRevealsOnlyBoundedCellsUntilExplored(){using(var r=new Rig()){var p=fixture.Approaches[2];Prepare(r.D,p);int before=r.D.Remembered.Count;r.W.Excavate(fixture.X+35,fixture.Y-4);r.D.ProcessChanges(p);Assert.That(r.D.Remembered.Count-before,Is.LessThanOrEqualTo(r.D.MaxWaveCells));Assert.That(Known(r.D,fixture.Centers[2]),Is.False);int count=r.D.Remembered.Count;for(int n=0;n<60;n++)r.D.Tick(.1);Assert.That(r.D.Remembered.Count,Is.EqualTo(count));r.D.Explore(fixture.P(35,-22));r.D.Explore(fixture.P(65,-22));Assert.That(r.D.Remembered.Count,Is.GreaterThan(count));Assert.That(Known(r.D,fixture.Centers[2]),Is.False);}}
  [Test]public void RevealDistanceIsGeodesicAndCannotCrossSealedDirt(){using(var r=new Rig()){r.D.RevealDistance=48;Prepare(r.D,fixture.Approaches[1]);Assert.That(Known(r.D,fixture.Centers[1]),Is.False);Assert.That(r.W.IsSolid(fixture.X-20,fixture.Y-4));}}
  [Test]public void TwoEntrancesUseSameIdentityAndNeverRediscover(){using(var r=new Rig()){Prepare(r.D,fixture.Approaches[3]);r.W.Excavate(fixture.X-64,fixture.Y+4);r.D.ProcessChanges(fixture.Approaches[3]);Settle(r.D);var id=index.ByCell[(int)fixture.Centers[3].Y*1024+(int)fixture.Centers[3].X].Id;Assert.That(r.D.DiscoveredRegions.Contains(id));int amount=r.D.Remembered.Count;Prepare(r.D,fixture.P(-46,2));int events=r.D.DiscoveryEvents;r.W.Excavate(fixture.X-46,fixture.Y+4);r.D.ProcessChanges(fixture.P(-46,2));Assert.That(r.D.DiscoveredRegions.Count(x=>x==id),Is.EqualTo(1));Assert.That(r.D.DiscoveryEvents,Is.EqualTo(events));Assert.That(r.D.Remembered.Count,Is.GreaterThanOrEqualTo(amount));}}
  [Test]public void AuthoredRegionSpansChunksAndUsesIndexedMembership(){var region=index.ById["fixture/cross-chunk"];var chunks=region.Cells.Select(i=>StreamingCoordinates.Owner(i%1024,i/1024)).Distinct().ToArray();Assert.That(chunks.Length,Is.GreaterThan(3));Assert.That(chunks.All(k=>index.ByChunk[k].Contains(region)));}
  [Test]public void ProtectedLandmarkRemainsPhysicalAndUndiggableDuringDiscovery(){using(var r=new Rig()){Prepare(r.D,fixture.Approaches[5]);r.W.Excavate(fixture.X+110,fixture.Y+4);r.D.ProcessChanges(fixture.Approaches[5]);Settle(r.D);Assert.That(r.W.IsSolid(fixture.X+110,fixture.Y+35));Assert.That(r.W.Excavate(fixture.X+110,fixture.Y+35),Is.False);Assert.That(index.ById["fixture/landmark"].Cells.Contains((fixture.Y+35)*1024+fixture.X+110),Is.False);}}
  [Test]public void RubbleHistoryAccessibilityAndPermanentEditsStaySeparate(){using(var r=new Rig()){Prepare(r.D,fixture.Approaches[6]);int x=fixture.X-5,y=fixture.Y+4;r.W.Excavate(x,y);r.D.ProcessChanges(fixture.Approaches[6]);Settle(r.D);int events=r.D.DiscoveryEvents;Assert.That(Known(r.D,fixture.Centers[6]));Assert.That(r.W.EditCount,Is.Zero);Assert.That(r.W.TemporaryOpenCells.Count,Is.EqualTo(1));Assert.That(HasPath(r.W,fixture.Approaches[6],fixture.Centers[6],1));Assert.That(r.W.Refill(x,y));Assert.That(Known(r.D,fixture.Centers[6]));Assert.That(HasPath(r.W,fixture.Approaches[6],fixture.Centers[6],1),Is.False);r.W.Excavate(x,y);r.D.ProcessChanges(fixture.Approaches[6]);Assert.That(r.D.DiscoveryEvents,Is.EqualTo(events));Assert.That(r.D.PendingReleases,Is.Zero);}}
  [Test]public void ArbitraryTerrainCannotBeRefilled(){using(var r=new Rig()){r.W.Excavate(fixture.X+15,fixture.Y+4);Assert.That(r.W.Refill(fixture.X+15,fixture.Y+4),Is.False);Assert.That(r.W.Refill(fixture.X+110,fixture.Y+35),Is.False);}}
  [Test]public void RememberedTerrainPersistsWhileLiveContentsNeedSight(){using(var r=new Rig()){Prepare(r.D,fixture.Approaches[1]);r.W.Excavate(fixture.X-20,fixture.Y-4);r.D.ProcessChanges(fixture.Approaches[1]);Settle(r.D);var actor=fixture.Centers[1];Assert.That(r.D.ContentAllowed(actor,actor));Assert.That(r.D.ContentAllowed(fixture.Entry,actor),Is.False);Assert.That(Known(r.D,actor));Assert.That(r.P.IsSolid((int)actor.X,(int)actor.Y),Is.False);}}
  [Test]public void HiddenDormantActorsExistAndSimulationDoesNotDependOnMemory(){using(var r=new Rig()){var a=new StreamingActor(fixture.Centers[2]);var b=new StreamingActor(fixture.Centers[2]);var bounds=new ProjectionBounds(new Point2(0,0),new Point2(1024,1024));a.Step(fixture.Entry,bounds,1,r.W);Assert.That(a.Active,Is.False);Assert.That(a.Clock,Is.Zero);Prepare(r.D,fixture.Centers[2]);b.Step(fixture.Entry,bounds,1,r.W);Assert.That(b.Position,Is.EqualTo(a.Position));Assert.That(b.Clock,Is.EqualTo(a.Clock));a.Step(fixture.Centers[2],bounds,1,r.W);b.Step(fixture.Centers[2],bounds,1,r.W);Assert.That(b.Position,Is.EqualTo(a.Position));Assert.That(a.Clock,Is.GreaterThan(0));}}
  [Test]public void ScriptedExistingActorApproachesFromUnseenRememberedFloor()
  {
   using(var r=new Rig()){var player=fixture.Approaches[1];Prepare(r.D,player);r.W.Excavate(fixture.X-20,fixture.Y-4);r.D.ProcessChanges(player);Settle(r.D);var center=fixture.Centers[1];var path=new List<Point2>();Assert.That(new LabNavigation(r.W,player).TraceToRoot(new Point2(center.X+8,center.Y),1,path));var actor=new LabActor();actor.Reset(0,"existing",path,1,true,LabAttack.ShortMelee);Assert.That(r.D.ContentAllowed(player,actor.Position),Is.False);bool seen=false;for(int n=0;n<600;n++){actor.Step(1.0/60,player,new LabTuning(),r.W);if(r.D.ContentAllowed(player,actor.Position))seen=true;}Assert.That(seen);Assert.That(actor.Clock,Is.GreaterThan(9));Assert.That(actor.SpawnValid);}
  }
  [Test]public void AlternateNetworkOpeningChangesLogicalConnectivity(){using(var r=new Rig()){var from=fixture.P(95,0);var to=fixture.P(190,0);Assert.That(HasPath(r.W,from,to,1),Is.False);r.W.Excavate(fixture.X+35,fixture.Y-4);r.W.Excavate(fixture.X+179,fixture.Y-4);Assert.That(HasPath(r.W,from,to,1));}}
  [Test]public void RoutineDigDoesNotRescanIndexOrWorld(){using(var r=new Rig()){Prepare(r.D,fixture.Approaches[1]);long before=r.W.Queries;r.W.Excavate(fixture.X-20,fixture.Y-4);r.D.ProcessChanges(fixture.Approaches[1]);Assert.That(r.W.Queries-before,Is.LessThan(50000));Assert.That(index.InitialQueries,Is.EqualTo(1048576));Assert.That(r.D.LastVisits,Is.LessThanOrEqualTo(8192));}}
  [Test]public void ClueMetadataDoesNotChangeOccupancyOrGuaranteeARegion(){using(var r=new Rig()){int before=r.W.Revision;foreach(var clue in fixture.Clues){clue.Position.ToString();}Assert.That(r.W.Revision,Is.EqualTo(before));Assert.That(fixture.Clues.Select(c=>c.Kind).Distinct().Count(),Is.EqualTo(4));var falseClue=fixture.Clues.Last();Assert.That(index.ByCell.ContainsKey((int)falseClue.Position.Y*1024+(int)falseClue.Position.X),Is.False);Assert.That(r.W.IsSolid((int)falseClue.Position.X,(int)falseClue.Position.Y));}}
  [Test]public void RememberedCellBitDeltasRoundTripWithRefilledEntrance(){using(var s=new DiscoveryExperiment()){Prepare(s.Discovery,s.Fixture.Approaches[6]);s.World.Excavate(s.Fixture.X-5,s.Fixture.Y+4);s.Discovery.ProcessChanges(s.Fixture.Approaches[6]);Settle(s.Discovery);s.World.Refill(s.Fixture.X-5,s.Fixture.Y+4);using(var stream=new MemoryStream()){s.Save(stream);Assert.That(stream.Length,Is.LessThan(5000));stream.Position=0;using(var b=DiscoveryExperiment.Load(stream)){Assert.That(b.Discovery.Remembered,Is.EquivalentTo(s.Discovery.Remembered));Assert.That(b.Discovery.Visual,Is.EquivalentTo(s.Discovery.Remembered));Assert.That(b.World.IsSolid(s.Fixture.X-5,s.Fixture.Y+4));Assert.That(b.Discovery.PendingReleases,Is.Zero);Assert.That(b.Index.Regions.Select(r=>r.Id),Is.EqualTo(s.Index.Regions.Select(r=>r.Id)));}}}}
  [Test]public void RevealNeverWritesOccupancyAndRestoresExactCanonicalGeometry(){using(var r=new Rig()){var original=new List<bool>();for(int y=530;y<552;y++)for(int x=540;x<580;x++)original.Add(r.W.IsSolid(x,y));r.D.Visual.UnionWith(index.ByCell.Keys);r.D.Remembered.UnionWith(index.ByCell.Keys);int n=0;for(int y=530;y<552;y++)for(int x=540;x<580;x++)Assert.That(r.W.IsSolid(x,y),Is.EqualTo(original[n++]));var a=PreviewMeshBuilder.BuildPatch(r.W,new ContourTerrainCache(r.W),544,528,16);var b=PreviewMeshBuilder.BuildPatch(r.P,new ContourTerrainCache(r.P),544,528,16);for(int k=0;k<4;k++){Assert.That(b[k].Vertices,Is.EqualTo(a[k].Vertices));Assert.That(b[k].Indices,Is.EqualTo(a[k].Indices));Assert.That(b[k].WallSamples,Is.EqualTo(a[k].WallSamples));}Assert.That(r.W.Revision,Is.Zero);}}
  [Test]public void HiddenGeometryHasNoFloorFacingWallsOrLipsInsideSealedRoom(){using(var r=new Rig()){var p=fixture.Centers[1];var key=StreamingCoordinates.Owner((int)p.X,(int)p.Y);var hidden=PreviewMeshBuilder.BuildPatch(r.P,new ContourTerrainCache(r.P),key.X*16,key.Y*16,16);Assert.That(hidden[1].Indices.Count,Is.Zero);Assert.That(hidden[2].Indices.Count,Is.Zero);Assert.That(r.W.IsSolid((int)p.X,(int)p.Y),Is.False);}}
  [Test]public void VisualChangesRebuildOnlyAffectedHaloAndPublishOneLocalBatch()
  {
   using(var r=new Rig())using(var stream=new StreamingGeometry(r.W,384,true,r.P))
   {
    var at=fixture.Approaches[1];var map=new FocusProjection(at,48,28,24,1,1,1,new Point2(0,0),true);for(int n=0;n<300;n++){stream.Select(map,64,48,2.15,0);stream.Pump(20,100);}Assert.That(stream.Ready);
    Prepare(r.D,at);while(r.D.PendingReleases>0)r.D.Tick(1);var cells=new List<DualTile>{new DualTile(fixture.X-20,fixture.Y-4)};stream.Dig(cells);var before=stream.Resident.ToDictionary(p=>p.Key,p=>p.Value.Revision);r.D.ProcessChanges(at);r.D.Tick(1);var expected=new HashSet<DualTile>();foreach(var cell in r.D.Released)for(int y=cell.Y-4;y<cell.Y+4;y++)for(int x=cell.X-4;x<cell.X+4;x++)expected.Add(StreamingCoordinates.Owner(x,y));stream.QueuePresentation(r.D.Released);stream.PumpPresentation(int.MaxValue,double.PositiveInfinity);Assert.That(stream.PendingPresentation,Is.Zero);int changed=0,retained=0;foreach(var pair in stream.Resident)if(pair.Value.Revision!=before[pair.Key]){changed++;Assert.That(expected.Contains(pair.Key));}else retained++;Assert.That(changed,Is.GreaterThan(0));Assert.That(retained,Is.GreaterThan(0));Assert.That(r.W.Revision,Is.EqualTo(1));
   }
  }
  [Test]public void PresentationRebuildsAreLocalAndCameraDoesNotInvalidateRetainedChunks()
  {
   Stage52Tools.Install();try{var env=UnityEngine.Object.FindAnyObjectByType<Stage52Preview>();env.Initialize();env.Lab.paused=true;var live=env.Live;for(int n=0;n<600;n++)live.Refresh(0);var retained=live.Stream.Resident.ToDictionary(p=>p.Key,p=>(p.Value,p.Value.Revision));int rebuilds=live.Stream.PresentationRebuilds,remembered=env.State.Discovery.Remembered.Count;for(int p=0;p<4;p++){env.Lab.CameraStudy.Apply(p);for(int n=0;n<200;n++)live.Refresh(0);env.Draw();}Assert.That(live.Stream.PresentationRebuilds,Is.EqualTo(rebuilds));Assert.That(env.State.Discovery.Remembered.Count,Is.EqualTo(remembered));foreach(var pair in live.Stream.Resident)if(retained.TryGetValue(pair.Key,out var before)&&ReferenceEquals(before.Item1,pair.Value))Assert.That(pair.Value.Revision,Is.EqualTo(before.Item2));for(int n=0;n<3;n++){env.ResetDemo();for(int j=0;j<500;j++)live.Refresh(0);Assert.That(env.OwnedMeshes,Is.EqualTo(13));Assert.That(env.GetComponentsInChildren<MeshFilter>().Count(f=>f.name.StartsWith("Stage52 batch")),Is.EqualTo(13));Assert.That(live.PooledPresentations,Is.LessThanOrEqualTo(8));}Assert.That(env.GetComponent<Stage51Preview>(),Is.Null);}
   finally{EditorSceneManager.NewScene(NewSceneSetup.EmptyScene);}
  }
 }
}
